insert into el_zhady_private.live_quiz_questions(id,set_version,ordinal,prompt,options,correct_option_id,explanation,source_refs) values
('30000000-0000-4000-8000-000000000001','kz-1939-1953-v1',1,'Екінші дүниежүзілік соғыс қай жылдары өтті?','[{"id": "q01_0", "text": "1939–1945"}, {"id": "q01_1", "text": "1941–1945"}, {"id": "q01_2", "text": "1914–1918"}, {"id": "q01_3", "text": "1946–1953"}]'::jsonb,'q01_0','Екінші дүниежүзілік соғыс 1939–1945 жылдары өтті. Бұл мерзімді Ұлы Отан соғысының 1941–1945 жылдарымен шатастырмау керек.','[{"title": "World War II Dates and Timeline", "url": "https://encyclopedia.ushmm.org/content/en/article/world-war-ii-key-dates", "locator": "Frequently Asked Questions: How long did WWII last?; When did WWII start/end?", "publisher": "United States Holocaust Memorial Museum", "checked_on": "2026-11-01"}, {"title": "Ұлы Отан соғысы жылдарында (1941–1945) еңбек армиясы қатарында болған шығысқазақстандықтар", "url": "https://www.gov.kz/memleket/entities/vko-cultura-arhiv/press/news/details/219432", "locator": "Тақырып; 1941–1945 жылдар туралы кіріспе", "publisher": "ШҚО мәдениет басқармасы / А. С. Пушкин атындағы кітапхана", "checked_on": "2026-11-01"}]'::jsonb),
('30000000-0000-4000-8000-000000000002','kz-1939-1953-v1',2,'Ұлы Отан соғысы қай жылдарды қамтиды?','[{"id": "q02_0", "text": "1941–1945"}, {"id": "q02_1", "text": "1939–1945"}, {"id": "q02_2", "text": "1914–1918"}, {"id": "q02_3", "text": "1946–1950"}]'::jsonb,'q02_0','Ұлы Отан соғысының мерзімі — 1941–1945 жылдар. Ол Екінші дүниежүзілік соғыстың аясында қарастырылады.','[{"title": "Ұлы Отан соғысы жылдарында (1941–1945) еңбек армиясы қатарында болған шығысқазақстандықтар", "url": "https://www.gov.kz/memleket/entities/vko-cultura-arhiv/press/news/details/219432", "locator": "Тақырып; 1941–1945 жылдар туралы кіріспе", "publisher": "ШҚО мәдениет басқармасы / А. С. Пушкин атындағы кітапхана", "checked_on": "2026-11-01"}, {"title": "World War II Dates and Timeline", "url": "https://encyclopedia.ushmm.org/content/en/article/world-war-ii-key-dates", "locator": "Frequently Asked Questions: How long did WWII last?; When did WWII start/end?", "publisher": "United States Holocaust Memorial Museum", "checked_on": "2026-11-01"}]'::jsonb),
('30000000-0000-4000-8000-000000000003','kz-1939-1953-v1',3,'1941 жылы 316-шы атқыштар дивизиясын басқарған генерал кім?','[{"id": "q03_0", "text": "Иван Панфилов"}, {"id": "q03_1", "text": "Бауыржан Момышұлы"}, {"id": "q03_2", "text": "Талғат Бигелдинов"}, {"id": "q03_3", "text": "Қасым Қайсенов"}]'::jsonb,'q03_0','Қазақ және Қырғыз КСР азаматтарынан жасақталған 316-шы атқыштар дивизиясын генерал-майор Иван Панфилов басқарды.','[{"title": "Алматыда панфиловшы батырларды еске алуға арналған іс-шара өтті", "url": "https://www.gov.kz/org/kvv/press/news/details/230718", "locator": "316-шы атқыштар дивизиясын И. В. Панфилов басқарғаны туралы абзац", "publisher": "Қазақстан Республикасы ІІМ Ұлттық ұланы", "checked_on": "2026-11-01"}]'::jsonb),
('30000000-0000-4000-8000-000000000004','kz-1939-1953-v1',4,'Мәншүк Мәметова ұрыста негізінен қай қаруды қолданған?','[{"id": "q04_0", "text": "Пулемет"}, {"id": "q04_1", "text": "Торпедо"}, {"id": "q04_2", "text": "Зеңбірек"}, {"id": "q04_3", "text": "Танк"}]'::jsonb,'q04_0','Мәншүк Мәметова пулеметші болған. Оның Невель түбіндегі ұрысы өмірбаяндық материалда пулеметпен байланыстырылады.','[{"title": "Мәншүк Мәметова", "url": "https://e-history.kz/kz/prominent-figures/show/12507", "locator": "Аға сержант, пулеметші Мәншүк туралы өмірбаян абзацы", "publisher": "Qazaqstan tarihy / e-history.kz", "checked_on": "2026-11-01"}]'::jsonb),
('30000000-0000-4000-8000-000000000005','kz-1939-1953-v1',5,'Әлия Молдағұлованың майдандағы әскери мамандығы қандай?','[{"id": "q05_0", "text": "Мерген"}, {"id": "q05_1", "text": "Әскери ұшқыш"}, {"id": "q05_2", "text": "Әскери дәрігер"}, {"id": "q05_3", "text": "Теңізші"}]'::jsonb,'q05_0','Әлия Молдағұлова майданда мерген ретінде қызмет етті. Тарихи материалда ол атқыштар бригадасының мергені деп көрсетілген.','[{"title": "Батыс қазақстандықтардың Ұлы Жеңіске қосқан үлесі", "url": "https://e-history.kz/kz/amp/news/show/50000239", "locator": "Әлия мен Мәншүк туралы абзац; майданға азық-түлік жіберу және тыл өндірісі туралы абзацтар", "publisher": "Qazaqstan tarihy / e-history.kz", "checked_on": "2026-11-01"}]'::jsonb),
('30000000-0000-4000-8000-000000000006','kz-1939-1953-v1',6,'Соғыс жылдарындағы тыл еңбегінің майданға көмегі қайсы?','[{"id": "q06_0", "text": "Азық-түлік пен әскери жабдық өндіру"}, {"id": "q06_1", "text": "Алғы шепте мергендік ұрыс жүргізу"}, {"id": "q06_2", "text": "Әуе шайқасында ұшақты басқару"}, {"id": "q06_3", "text": "Теңізде жауынгерлік шабуыл жасау"}]'::jsonb,'q06_0','Тылдағы еңбек майданды азық-түлікпен, киіммен және әскери жабдықпен қамтамасыз етуге көмектесті. Деректе азық-түлік жөнелту мен өндіріс жұмысы сипатталған.','[{"title": "Батыс қазақстандықтардың Ұлы Жеңіске қосқан үлесі", "url": "https://e-history.kz/kz/amp/news/show/50000239", "locator": "Әлия мен Мәншүк туралы абзац; майданға азық-түлік жіберу және тыл өндірісі туралы абзацтар", "publisher": "Qazaqstan tarihy / e-history.kz", "checked_on": "2026-11-01"}]'::jsonb),
('30000000-0000-4000-8000-000000000007','kz-1939-1953-v1',7,'1946–1950 жылдардағы бесжылдық жоспар қай міндетке бағытталды?','[{"id": "q07_0", "text": "Соғыстан кейінгі шаруашылықты қалпына келтіру және дамыту"}, {"id": "q07_1", "text": "Адамды ғарышқа ұшыру"}, {"id": "q07_2", "text": "Тың игеру науқанын бастау"}, {"id": "q07_3", "text": "Нарықтық жекешелендіру жүргізу"}]'::jsonb,'q07_0','1946 жылы қабылданған бесжылдық жоспар соғыстан кейінгі халық шаруашылығын қалпына келтіру мен дамытуға арналды.','[{"title": "Влияние левацкой политики КПСС на Коммунистическую партию Казахстана", "url": "https://e-history.kz/media/scorm/431/text/text.htm", "locator": "Хронология: март 1946 г., план восстановления на 1946–1950 гг.", "publisher": "Qazaqstan tarihy / e-history.kz, оқу материалы", "checked_on": "2026-11-01"}]'::jsonb),
('30000000-0000-4000-8000-000000000008','kz-1939-1953-v1',8,'1946 жылы құрылған Қазақ КСР Ғылым академиясының тұңғыш президенті кім?','[{"id": "q08_0", "text": "Қаныш Сәтбаев"}, {"id": "q08_1", "text": "Әлкей Марғұлан"}, {"id": "q08_2", "text": "Мұхтар Әуезов"}, {"id": "q08_3", "text": "Ермұхан Бекмаханов"}]'::jsonb,'q08_0','Қазақ КСР Ғылым академиясының құрылған күні — 1946 жылғы 1 маусым. Оның тұңғыш президенті Қаныш Имантайұлы Сәтбаев болды.','[{"title": "ҚР ҰҒА тарихы", "url": "https://qazscience.gov.kz/category/history-of-nas-rk", "locator": "1946 жылғы 1 маусым: академияның құрылуы және тұңғыш президенті", "publisher": "Қазақстан Республикасы Президентінің жанындағы Ұлттық ғылым академиясы", "checked_on": "2026-11-01"}]'::jsonb),
('30000000-0000-4000-8000-000000000009','kz-1939-1953-v1',9,'«Абай жолы» эпопеясының авторы кім?','[{"id": "q09_0", "text": "Мұхтар Әуезов"}, {"id": "q09_1", "text": "Сәбит Мұқанов"}, {"id": "q09_2", "text": "Ғабит Мүсірепов"}, {"id": "q09_3", "text": "Сәкен Сейфуллин"}]'::jsonb,'q09_0','Автор — Мұхтар Әуезов. Абай туралы романның алғашқы кітабы 1942 жылы жарық көрген; эпопеяның түгел аяқталуын 1953 жылға дейінгі кезеңге жатқызбаймыз.','[{"title": "Уникальное издание «Абай жолы» 1942 года стало источником научных исследований", "url": "https://www.gov.kz/org/sci/press/news/details/1271394?lang=ru", "locator": "1942 жылғы басылым және Мұхтар Әуезов авторлығы туралы алғашқы абзац", "publisher": "Қазақстан Республикасы Ғылым және жоғары білім министрлігі", "checked_on": "2026-11-01"}]'::jsonb),
('30000000-0000-4000-8000-000000000010','kz-1939-1953-v1',10,'1952 жылы саяси қудалау кезінде 25 жылға сотталған тарихшы кім?','[{"id": "q10_0", "text": "Ермұхан Бекмаханов"}, {"id": "q10_1", "text": "Қаныш Сәтбаев"}, {"id": "q10_2", "text": "Мұхтар Әуезов"}, {"id": "q10_3", "text": "Әлкей Марғұлан"}]'::jsonb,'q10_0','Тарихшы Ермұхан Бекмаханов 1952 жылы саяси қудалау кезінде 25 жылға бас бостандығынан айырылды.','[{"title": "Қоғамдық-саяси және мәдени өмірдегі өзгерістер", "url": "https://e-history.kz/kz/amp/history-of-kazakhstan/show/8825", "locator": "Е. Бекмахановтың 1952 жылы 25 жылға сотталғаны туралы абзац", "publisher": "Qazaqstan tarihy / e-history.kz", "checked_on": "2026-11-01"}]'::jsonb);
